package com.soulsync.domain;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID; import com.soulsync.domain.Enums.*;
@Entity @Table(name="messages") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Message { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="conversation_id",nullable=false) private Conversation conversation; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="sender_id",nullable=false) private User sender; @Column(nullable=false,length=4000) private String body; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private MessageType type=MessageType.TEXT; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private MessageStatus status=MessageStatus.SENT; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="read_at") private Instant readAt; @PrePersist void pre(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();} }
